"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2931],{50099:e=>{e.exports=JSON.parse('{"functions":[{"name":"init","desc":"Registers the player collision group so characters can be assigned to it as\\nsoon as they spawn.","params":[],"returns":[],"function_type":"static","source":{"line":36,"path":"src/Server/Features/Core/CollisionService.luau"}},{"name":"addGroup","desc":"Registers a collision group if it does not already exist. Safe to call\\nrepeatedly \u2014 raw `RegisterCollisionGroup` errors on a duplicate.","params":[{"name":"group","desc":"collision group name","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":60,"path":"src/Server/Features/Core/CollisionService.luau"}},{"name":"setCollidable","desc":"Sets whether two collision groups collide, registering both first so the\\ncall cannot fail on an unknown group.","params":[{"name":"group","desc":"first collision group","lua_type":"string"},{"name":"group2","desc":"second collision group","lua_type":"string"},{"name":"collidable","desc":"whether they should collide","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":77,"path":"src/Server/Features/Core/CollisionService.luau"}},{"name":"preventGroupCollision","desc":"Prevents members of a group from colliding with each other \u2014 shorthand for\\n`CollisionGroupSetCollidable(group, group, false)`. Used to let characters\\npass through one another.\\n\\nUnlike the other entry points this does **not** register the group first, so\\nthe group must already exist.","params":[{"name":"group","desc":"collision group name","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":101,"path":"src/Server/Features/Core/CollisionService.luau"}},{"name":"setCollisionGroup","desc":"Assigns every BasePart in an instance\'s tree \u2014 the instance itself plus all\\ndescendants \u2014 to a collision group, registering the group first.\\n\\nApplied to whole character models by [PlayerService], which is why it walks\\ndescendants rather than taking a single part.","params":[{"name":"instance","desc":"root of the tree to assign","lua_type":"Instance"},{"name":"group","desc":"collision group name","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":118,"path":"src/Server/Features/Core/CollisionService.luau"}}],"properties":[],"types":[],"name":"CollisionService","desc":"Thin wrapper over `PhysicsService` collision groups.\\n\\nIts one real job is making group registration idempotent: Roblox errors when\\na group is registered twice, so every entry point routes through\\n[CollisionService.addGroup], which checks first. That lets callers name a\\ngroup without caring whether it already exists.\\n\\n`PLAYER_COLLISION` is re-exported from `PlayerData` so callers do not need\\nboth requires; [PlayerService] applies it to every spawned character.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","realm":["Server"],"source":{"line":18,"path":"src/Server/Features/Core/CollisionService.luau"}}')}}]);